SourceCode.Declaration:
#AVAWHSRF
/// <summary> 
/// The <c>ALNWHSControlPrinterCode</c> class is responsible for handling the printer code validation 
/// </summary>
[ 
    WhsControlFactory(#AVAPrinterCode)
] 
class AVAWHSControlPrinterCode extends WHSControl
{
}

Method.Source:
/// <summary>
/// process the Control logic
/// </summary>
/// <returns>
/// return true if process complete
/// </returns>
public boolean process()
{ 
    SysCorpNetActivePrinters   sysCorpNetActivePrinters;

    sysCorpNetActivePrinters = SysCorpNetActivePrinters::avaFindByPrinterName(this.parmData());

    if (!sysCorpNetActivePrinters)
    {
        return this.fail(strFmt("@NDX:AVAError_PrinterDoesNotExist", this.parmData()));
    }
    else 
    {
        if (!AVAWHSWorkUserPrinter::exist(pass.parmUserId(), this.parmData()))
        { 
            return this.fail(strFmt("@NDX:AVAError_PrinterDoesNotAssignedTo", this.parmData()));
        }
    }

    fieldValues.avaParmPrinterCode(this.parmData()); 

    return true;
}
